package com.servicedesk360.service;
import com.servicedesk360.dto.audit.*; import com.servicedesk360.dto.common.*; import com.servicedesk360.entity.*; import com.servicedesk360.exception.*; import com.servicedesk360.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuditLogService{private final AuditLogRepository repo;private final CurrentUserService current;public AuditLogService(AuditLogRepository r,CurrentUserService c){repo=r;current=c;} @Transactional public AuditLog append(String action,String type,Long id,String details){var me=current.getRequiredUser();return repo.save(new AuditLog(me.tenantId(),me.user().getId(),action,type,id,details));} @Transactional(readOnly=true) public PageResponse<AuditLogResponse> list(Pageable p){var me=current.getRequiredUser();if(me.role()!=Role.TENANT_ADMIN)throw new UnauthorizedException("Tenant administrator role required");return PageResponse.from(repo.findAllByTenantId(me.tenantId(),p).map(AuditLogResponse::from));}}
